const phaseLabel=p=>({queued:'Waiting for a worker',provisioning:'Provisioning GPU',uploading:'Uploading dataset',installing:'Preparing environment',loading_model:'Loading base model',training:'Training adapter',evaluating_base:'Evaluating base',evaluating_adapter:'Evaluating LoRA',saving:'Saving adapter',collecting:'Returning artifacts',done:'Run completed'}[p]||p||'Not started');
function notify(text,error=false){const n=document.createElement('div');n.className='portal-toast '+(error?'error':'success');n.textContent=text;$('toast-stack').append(n);setTimeout(()=>n.remove(),6500);}
const BASE=location.pathname.startsWith('/portal')?'/portal':'';
async function api(path,payload){if(preview&&payload!==undefined)throw Error('Demo is read-only. Return to live data to use this action.');const r=await fetch(BASE+path,{headers:payload!==undefined?{'Content-Type':'application/json'}:{},...(payload!==undefined?{method:'POST',body:JSON.stringify(payload)}:{})});let d;try{d=await r.json();}catch{throw Error('The control API returned a non-JSON response. Check the reverse proxy.');}if(!r.ok){if(r.status===401&&d.auth)throw new AuthError();throw Error(d.error||`HTTP ${r.status}`);}return d;}
async function confirmAction(title,copy){$('confirm-title').textContent=title;$('confirm-copy').textContent=copy;const d=$('confirm-dialog');d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='confirm'),{once:true}));}
function drawChart(series){const rows=(series||[]).filter(p=>Number.isFinite(p.loss));if(!rows.length)return empty('Waiting for training telemetry','Loss values appear here as the trainer records steps. Nothing is simulated.', '', 'runs');const w=680,h=170,left=37,right=12,top=12,bottom=26;const vals=rows.map(x=>x.loss),min=Math.max(0,Math.min(...vals)*.8),max=Math.max(...vals)*1.1||1;const maxStep=Math.max(1,...rows.map(x=>x.step));const x=v=>left+v/maxStep*(w-left-right),y=v=>top+(max-v)/(max-min)*(h-top-bottom);const line=rows.map((p,i)=>(i?'L':'M')+x(p.step).toFixed(1)+','+y(p.loss).toFixed(1)).join(' ');return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Training loss by step"><defs><linearGradient id="loss-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#bfa8ef" stop-opacity=".22"/><stop offset="100%" stop-color="#bfa8ef" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return `<line class="chart-grid" x1="${left}" x2="${w-right}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-label" x="0" y="${y(v)+3}">${v.toFixed(2)}</text>`;}).join('')}<path d="${line} L${x(rows.at(-1).step)},${h-bottom} L${x(rows[0].step)},${h-bottom}Z" fill="url(#loss-fill)"/><path d="${line}" class="chart-line"/>${rows.map(p=>`<circle cx="${x(p.step)}" cy="${y(p.loss)}" r="2" fill="#9479d5"><title>Step ${p.step} · loss ${p.loss}</title></circle>`).join('')}${[0,1,2,3,4].map(i=>`<text class="chart-label" x="${x(maxStep*i/4)}" y="${h-5}" text-anchor="middle">${Math.round(maxStep*i/4)}</text>`).join('')}</svg>`;}
function comparisons(rep){if(!rep?.base||!rep?.lora)return empty('Measure the difference','Complete a run to compare base and adapter on the same held-out examples.','','compare');const b=rep.base,l=rep.lora;return [['Slice accuracy','exact_slices','total_slices'],['Valid JSON','valid_json_and_schema','examples'],['Exact responses','exact_arrays','examples']].map(([name,k,n])=>{const before=pct(b[k],b[n]),after=pct(l[k],l[n]);return `<div class="comparison-row"><div class="comparison-label"><span>${name}</span><span>${before}% <span class="muted">→</span> ${after}% <span class="delta">&nbsp;${after-before>=0?'+':''}${after-before} pp</span></span></div><div class="comparison-bars"><div class="comparison-bar"><i style="width:${before}%"></i></div><div class="comparison-bar after"><i style="width:${after}%"></i></div></div></div>`;}).join('')+'<div class="comparison-footer"><span><i></i>Base model</span><span><i class="after"></i>Fine-tuned adapter</span></div>';}
function runsTable(rows){if(!rows.length)return empty('Your first experiment starts here','Import a dataset, choose a preset and run a reproducible Base → LoRA comparison.',button('Create experiment','new-run','plus'),'runs');return `<div class="table-responsive"><table class="table"><thead><tr><th>Experiment / dataset</th><th>Status</th><th>Compute</th><th>Accuracy</th><th>Created</th><th></th></tr></thead><tbody>${rows.map(j=>`<tr><td><strong>${esc(j.source_dataset||j.id)}</strong><small class="mono">${short(j.id)} · ${esc(j.preset)}</small></td><td>${stateBadge(j.status.state)}<small>${esc(phaseLabel(j.progress?.phase||j.status.phase))}</small></td><td>${esc(j.executor==='vast'?'Vast.ai GPU':j.device.toUpperCase())}<small>${esc(j.model?.split('/').at(-1)||'Qwen / LoRA')}</small></td><td>${j.metrics?.lora?`${pct(j.metrics.lora.exact_slices,j.metrics.lora.total_slices)}%`:'—'}<small>${j.gates?j.gates.passed?'Release eligible':'Review required':'Awaiting evaluation'}</small></td><td class="mono">${date(j.created_at)}</td><td>${button('Open','open-run','arrow','link',`data-id="${j.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;}
const phaseHuman=phaseLabel;
function currentRun(){return state.jobs.find(x=>x.status.state==='running')||state.jobs.find(x=>x.status.state==='queued')||state.jobs[0];}
const STEPS=[['Register','Create an account — the workspace is private to you.'],['Enter vast.ai API key','Get a key at cloud.vast.ai; paste it in Advanced. Training spins up on-demand RTX 3090 / 4090.'],['Upload Excel / CSV / TXT','Files are converted to immutable JSONL dataset versions with schema and leakage checks.'],['Define acceptance criteria','Min held-out examples, min accuracy, valid JSON rate, no regression — enforced before activation.'],['Train','One click rents an RTX 3090/4090, uploads your data, trains a LoRA adapter and evaluates before vs after. Smoke ≈10 min; standard (160 steps) ≈30 min.'],['Download','Grab the adapter ZIP (~30 MB): weights, config, tokenizer and the evaluation report.']];
function promo(){return `<section class="promo-hero"><div class="promo-brand">DILDO MLL</div><p class="promo-slogan">Finetune for everyone</p><p class="promo-formula">Qwen3.5 + vast.ai API key = <strong>a trained adapter in ~10 minutes, from $0.03</strong></p><div class="d-flex gap-2 justify-content-center mt-4 flex-wrap"><a class="btn btn-primary btn-lg" href="#live">Start training ${icon('arrow')}</a><a class="btn btn-outline-secondary btn-lg" href="#advanced">Configuration ${icon('settings')}</a></div></section>
<section class="panel"><div class="panel-head"><h2>Six steps from spreadsheet to model</h2></div><div class="steps-row">${STEPS.map(([t,d],i)=>`<div class="step-card"><div class="step-num">${i+1}</div><strong>${t}</strong><p>${d}</p></div>`).join('')}</div></section>
<section class="panel"><div class="panel-head"><h2>How it works · technical overview</h2></div><div class="promo-tech"><div><h3>What for</h3><p>The platform turns messy tracker or business data into a specialized decision model. Your base model (Qwen3.5-0.8B) answers generically; a LoRA adapter teaches it your exact policies — which ad slices to pause, hold or scale — in strict JSON the downstream systems can consume without parsing.</p></div><div><h3>Data preparation</h3><p>Excel / CSV / TXT is parsed into <strong>input/output pairs</strong>: each line holds one snapshot (<code>as_of</code>, list of ad slices with clicks, conversions, profit, maturity) and the expected decision array. Imports are validated against the trainer schema, deduplicated and leak-checked — test timestamps must be strictly newer than training ones. Versions are immutable: a run records the dataset hash it trained on.</p></div><div><h3>Training technology</h3><p><strong>LoRA (rank 8, α 16)</strong> on Qwen3.5-0.8B-Base: instead of rewriting 0.8 B parameters, a ~30 MB low-rank residual is trained — hence the price. The trainer (transformers 5.4 + PEFT) runs on an on-demand Vast.ai GPU: the control plane rents it, uploads data and code over SSH, streams live progress back, collects artifacts and releases the instance so idle seconds cost nothing. Measured on a $0.17/h RTX 3090: smoke (12 steps) finishes end-to-end in ~10 min for ~$0.03; standard (160 steps) in ~30 min for $0.08–0.12, depending on the host.</p></div><div><h3>Quality gates &amp; delivery</h3><p>Before anything ships, the finished adapter is evaluated on held-out examples against the base model: slice accuracy, valid-JSON rate and no-regression criteria must pass, otherwise activation is blocked. Passed adapters can be activated for hot testing (the model stays resident in RAM), probed with your own data on the LIVE page, and downloaded as a portable PEFT bundle for deployment anywhere.</p></div></div></section>`;}
